#!/bin/bash

################################################################################
# Script: compare_with_phase3.sh
# Purpose: Compare high-confidence genes (|Std iHS| ≥ 6) with Phase 3 results
# Author: Generated by Claude Code
# Date: 2025-10-30
################################################################################

# Set working directory
cd /home/vanbruggenmit/mit-ihh-pib/people/vanbruggenmit/mit-ihh-pib/results/analysis/high_significance_genes

echo "======================================================================="
echo "STEP 1: Extract unique protein-coding genes from high-significance SNPs"
echo "======================================================================="

# Extract protein-coding genes from gene_details_complete.tsv
# Skip header (NR>1), filter for protein-coding only ($2=="protein-coding")
# Extract gene symbol ($1), sort and get unique entries
awk -F'\t' 'NR>1 && $2=="protein-coding" {print $1}' gene_details_complete.tsv | \
  sort | \
  uniq > high_confidence_X_genes.txt

echo "High-confidence genes extracted: $(wc -l < high_confidence_X_genes.txt)"
echo ""
cat high_confidence_X_genes.txt
echo ""

echo "======================================================================="
echo "STEP 2: Find overlap between high-confidence and Phase 3 genes"
echo "======================================================================="

# comm command compares two SORTED files:
# comm -12 shows lines present in BOTH files (column 1 AND 2)
comm -12 \
  <(sort high_confidence_X_genes.txt) \
  <(sort ../gene_annotation/gene_name_lists/X_protein_coding_genes.txt) \
  > overlap_genes.txt

echo "Overlap genes (present in BOTH lists):"
cat overlap_genes.txt
echo ""

echo "=== SUMMARY ==="
echo "High-confidence genes: $(wc -l < high_confidence_X_genes.txt)"
echo "Phase 3 genes: $(wc -l < ../gene_annotation/gene_name_lists/X_protein_coding_genes.txt)"
echo "Overlap genes: $(wc -l < overlap_genes.txt)"
echo "Overlap percentage: $(awk -v overlap=$(wc -l < overlap_genes.txt) -v total=$(wc -l < high_confidence_X_genes.txt) 'BEGIN {printf "%.1f%%", (overlap/total)*100}')"
echo ""

echo "======================================================================="
echo "STEP 3: Find genes NOT in Phase 3 list"
echo "======================================================================="

# comm -23 shows lines present in file 1 but NOT in file 2
comm -23 \
  <(sort high_confidence_X_genes.txt) \
  <(sort ../gene_annotation/gene_name_lists/X_protein_coding_genes.txt) \
  > genes_not_in_phase3.txt

echo "High-confidence genes NOT in Phase 3 list:"
cat genes_not_in_phase3.txt
echo ""
echo "Genes NOT in Phase 3: $(wc -l < genes_not_in_phase3.txt)"
echo ""

echo "======================================================================="
echo "STEP 4: Investigate WHY these genes are not in Phase 3"
echo "======================================================================="

echo "Checking SNP mappings for genes not in Phase 3..."
echo ""

# For each gene not in Phase 3, find its SNP mappings
for gene in $(cat genes_not_in_phase3.txt); do
  echo "--- Gene: $gene ---"

  # Extract SNP mapping info for this gene
  # Shows: SNP ID, chromosome, position, gene, gene_start, gene_end, distance, location type
  grep -E "\b${gene}\b" snp_to_gene_mapping.tsv | head -1 | \
    awk -F'\t' '{
      print "SNP ID: " $1
      print "SNP Position: " $3
      print "Gene: " $4
      print "Gene Coordinates: " $5 "-" $6
      print "Distance from SNP: " $8 " bp"
      print "Location Type: " $9 " (" $10 ")"
    }'

  # Calculate distance in kb for easier interpretation
  grep -E "\b${gene}\b" snp_to_gene_mapping.tsv | head -1 | \
    awk -F'\t' '{
      distance_kb = $8 / 1000
      printf "Distance: %.1f kb %s\n", distance_kb, $10
    }'

  echo ""
done

echo "======================================================================="
echo "INTERPRETATION:"
echo "======================================================================="
cat << 'EOF'

The two genes NOT in Phase 3 (KLHL13 and PCDH11X) are both associated with
SNPs that are very far away (>400 kb):

- KLHL13: SNP is ~473 kb DOWNSTREAM
- PCDH11X: SNP is ~439 kb UPSTREAM

These genes were identified only because they are the "nearest gene" to
high-significance SNPs, but the actual selection signal is likely acting
on other genes or regulatory regions.

This is why they don't appear in the Phase 3 list - the Phase 3 analysis
looked for genes within regions with sustained high iHS signals, not just
single SNPs with nearby genes.

The 11 OVERLAP GENES have the strongest evidence because they:
1. Are near high-significance SNPs (|Std iHS| ≥ 6)
2. Are within regions identified in Phase 3 (|Std iHS| ≥ 2.9)
3. Have sustained selection signals across their genomic regions

EOF

echo "======================================================================="
echo "STEP 5: Create detailed comparison for overlap genes"
echo "======================================================================="

echo "Creating detailed file with functional categories for overlap genes..."

# Create a detailed comparison table
echo -e "gene_symbol\tfunctional_category\tin_phase3\tnear_high_sig_SNP" > overlap_genes_detailed.tsv

for gene in $(cat overlap_genes.txt); do
  # Get functional category from gene_details_complete.tsv
  category=$(awk -F'\t' -v g="$gene" '$1==g {print $11}' gene_details_complete.tsv)
  echo -e "$gene\t$category\tYES\tYES" >> overlap_genes_detailed.tsv
done

echo "Overlap genes by functional category:"
awk -F'\t' 'NR>1 {print $2}' overlap_genes_detailed.tsv | sort | uniq -c | sort -rn

echo ""
echo "======================================================================="
echo "FILES CREATED:"
echo "======================================================================="
echo "1. high_confidence_X_genes.txt - 13 protein-coding genes from high-sig SNPs"
echo "2. overlap_genes.txt - 11 genes in BOTH lists (strongest evidence)"
echo "3. genes_not_in_phase3.txt - 2 genes only in high-confidence list"
echo "4. overlap_genes_detailed.tsv - Detailed info for overlap genes"
echo "5. phase3_comparison_summary.txt - Full analysis summary"
echo ""
